import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { jobSeeker } from 'src/app/auth/Models/jobSeeker';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';

@Component({
  selector: 'app-edit-profile',
  templateUrl: './edit-profile.component.html',
  styleUrls: ['./edit-profile.component.css']
})
export class EditProfileComponent implements OnInit {

  jobSeeker!: jobSeeker;

  // Editable form fields, kept separate from the loaded model until saved.
  firstName = '';
  lastName = '';
  email = '';
  location = '';
  skillsText = '';

  saving = false;

  constructor(
    private jobSeekerService: JobseekerService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.getJobSeekerById();
  }

  getJobSeekerById(): void {
    const id = Number(localStorage.getItem('id'));
    this.jobSeekerService.getJobSeekerById(id).subscribe({
      next: (result) => {
        this.jobSeeker = result;
        this.firstName = result.firstName || '';
        this.lastName = result.lastName || '';
        this.email = result.email || '';
        this.location = result.location || '';
        this.skillsText = (result.skills || []).join(', ');
      },
      error: (err) => { console.log(err); }
    });
  }

  save(): void {
    const id = Number(localStorage.getItem('id'));
    const updated: Partial<jobSeeker> = {
      firstName: this.firstName,
      lastName: this.lastName,
      email: this.email,
      location: this.location,
      skills: this.skillsText
        .split(',')
        .map(s => s.trim())
        .filter(s => s.length > 0)
    };

    this.saving = true;
    this.jobSeekerService.updateJobSeeker(id, updated).subscribe({
      next: () => {
        this.saving = false;
        this.router.navigateByUrl('/seeker/profile-jobseeker');
      },
      error: (err) => {
        this.saving = false;
        console.log(err);
        alert('Could not save changes. Please try again.');
      }
    });
  }
}
<div class="page">
<app-header variant="seeker"></app-header>
<div class="app-shell">
<app-sidebar variant="seeker"></app-sidebar>
<main class="main">

<div class="page-title">Edit Profile</div>
<div class="form-card">
  <div class="card-row">
    <div class="field"><label>First name</label><input [(ngModel)]="firstName" name="firstName"></div>
    <div class="field"><label>Last name</label><input [(ngModel)]="lastName" name="lastName"></div>
  </div>
  <div class="field"><label>Email</label><input [(ngModel)]="email" name="email"></div>
  <div class="field"><label>Location</label><input [(ngModel)]="location" name="location"></div>
  <div class="field"><label>Skills (comma separated)</label><input [(ngModel)]="skillsText" name="skillsText"></div>
  <div class="form-actions">
    <button class="btn btn-primary" [disabled]="saving" (click)="save()">{{ saving ? 'Saving…' : 'Save changes' }}</button>
    <a routerLink="/seeker/profile-jobseeker" class="btn btn-secondary">Cancel</a>
  </div>
  <div class="danger-zone">
    <button class="btn btn-outline-danger">Delete my account</button>
  </div>
</div>

</main>
</div>
</div>
